def standard():
    x = Symbol('x')
    def ok(pv, qv, tv):
        f = (x - pv)*(x - qv)
        d = expand(f + f.subs(x, x - tv))
        n = expand((2*x + 1)*f)
        rs = roots(Poly(d, x))
        for r, md in rs.items():
            if im(r) != 0:
                continue
            mn, poly = 0, Poly(n, x)
            while poly.eval(r) == 0:
                poly = Poly(quo(poly.as_expr(), x - r), x)
                mn += 1
            if mn < md:
                return False
        return True
    vals = [Rational(k, 2) for k in range(-6, 3)]
    tests = [Rational(1), Rational(5, 4), Rational(7, 5), Rational(3, 2), Rational(2)]
    found = []
    for pv in vals:
        for qv in vals:
            if pv < qv and [ok(pv, qv, t) for t in tests] == [False, False, False, True, True]:
                found.append((pv, qv))
    assert len(found) == 1
    pv, qv = found[0]
    return (2 - pv)*(2 - qv)

