def standard():
    from fractions import Fraction as Fr
    eps = Fr(1, 10**9)
    def d_poly(coefs):
        return [c*(len(coefs) - 1 - i) for i, c in enumerate(coefs[:-1])]
    def ev(coefs, u):
        v = Fr(0)
        for c in coefs:
            v = v*u + c
        return v
    def ok(al, be, a):
        f = [Fr(1), -(2*al + be), al*al + 2*al*be, -al*al*be]       # (x-al)^2 (x-be)
        fp = d_poly(f)
        r1, r2, r3 = Fr(1), a, 4 - a
        P = [Fr(1), -(r1 + r2 + r3), r1*r2 + r1*r3 + r2*r3, -r1*r2*r3]
        Pp = d_poly(P)
        for p in {r1, r2, r3, al, be}:
            slopes = []
            for side in (-1, 1):
                u = p + side*eps
                fv, pv = ev(f, u), ev(P, u)
                gp = -ev(fp, p) if fv >= 0 else 7*ev(fp, p)
                ap = ev(Pp, p) if pv >= 0 else -ev(Pp, p)
                slopes.append(gp + ap)
            if abs(slopes[0] - slopes[1]) > Fr(1, 10**4):
                return False
        return True
    vals = []
    grid = [Fr(k, 4) for k in range(-16, 33)]
    for a in [Fr(k, 2) for k in range(-2, 11)]:
        for al in grid:
            for be in grid:
                if al != be and ok(al, be, a):
                    vals.append(-al*al*be)
    return max(vals)*min(vals)

