def standard():
    from itertools import product
    start = tuple('AAABBB')
    def sw(c, k):
        c = list(c)
        if k <= 5:
            c[k-1], c[k] = c[k], c[k-1]
        return tuple(c)
    tot = fav = 0
    for rolls in product(range(1, 7), repeat=4):
        c = start
        for k in rolls:
            c = sw(c, k)
        if c == start:
            tot += 1
            fav += rolls[2] == 6
    fr = Fraction(fav, tot)
    return fr.numerator + fr.denominator

